package br.com.erp.finance;
import br.com.erp.auth.*;
import br.com.erp.inventory.StockService;
import br.com.erp.shared.Audit;
import jakarta.validation.Validator;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;
import static br.com.erp.finance.ReconciliationContracts.*;
@Service
public class ReconciliationService {
 private final JdbcTemplate db;private final TreasuryService treasury;private final Audit audit;private final Validator validator;private final ZoneId zone;
 public ReconciliationService(JdbcTemplate db,TreasuryService treasury,Audit audit,Validator validator,@Value("${erp.finance-zone:America/Sao_Paulo}") String zone){this.db=db;this.treasury=treasury;this.audit=audit;this.validator=validator;this.zone=ZoneId.of(zone);}
 private ResponseStatusException error(HttpStatus status,String message){return new ResponseStatusException(status,message);}
 public Map<String,String> calendar(){return Map.of("date",LocalDate.now(zone).toString(),"zone",zone.getId());}
 private void lock(Actor a){db.queryForObject("SELECT id FROM tenant WHERE id=? FOR UPDATE",UUID.class,a.tenantId());}
 private void account(Actor a,UUID id){if(treasury.get(a,id).kind()!=TreasuryContracts.Kind.BANK)throw error(HttpStatus.BAD_REQUEST,"Selecione uma conta de banco para o extrato.");}
 private Line row(java.sql.ResultSet r,int i)throws java.sql.SQLException{return new Line(r.getObject("id",UUID.class),r.getObject("account_id",UUID.class),r.getString("external_id"),r.getObject("posted_on",LocalDate.class),r.getBigDecimal("amount"),r.getString("description"),r.getString("status"),r.getLong("version"),r.getObject("matched_entry_id",UUID.class),r.getString("review_note"),r.getObject("reviewed_by",UUID.class),r.getObject("reviewed_at",OffsetDateTime.class));}
 private Line find(Actor a,UUID id){var rows=db.query("SELECT * FROM bank_statement_line WHERE tenant_id=? AND id=?",this::row,a.tenantId(),id);if(rows.isEmpty())throw error(HttpStatus.NOT_FOUND,"Lançamento de extrato não encontrado.");account(a,rows.getFirst().accountId());return rows.getFirst();}
 @Transactional(readOnly=true) public Line get(Actor a,UUID id){return find(a,id);}
 private ImportView imported(Actor a,UUID id){var rows=db.query("SELECT * FROM bank_import WHERE tenant_id=? AND id=?",(r,i)->new ImportView(r.getObject("id",UUID.class),r.getObject("account_id",UUID.class),r.getString("reference"),r.getInt("new_count"),r.getInt("reused_count"),r.getObject("created_by",UUID.class),r.getObject("created_at",OffsetDateTime.class)),a.tenantId(),id);if(rows.isEmpty())throw error(HttpStatus.NOT_FOUND,"Importação não encontrada.");account(a,rows.getFirst().accountId());return rows.getFirst();}
 @Transactional public ImportView importCsv(Actor a,CsvInput input){return importLines(a,StatementCsv.parse(input));}
 private TreeMap<String,LineInput> normalize(Input input){
  if(!validator.validate(input).isEmpty())throw error(HttpStatus.BAD_REQUEST,"Informe de um a 500 lançamentos, com campos válidos.");
  var normalized=new TreeMap<String,LineInput>();LocalDate today=LocalDate.now(zone);
  for(var l:input.lines()){String key=l.externalId().trim();if(l.amount().signum()==0||l.postedOn().getYear()<1||l.postedOn().isAfter(today))throw error(HttpStatus.BAD_REQUEST,"Lançamento exige valor não zero e data válida até hoje.");if(normalized.put(key,new LineInput(key,l.postedOn(),l.amount(),l.description().trim()))!=null)throw error(HttpStatus.BAD_REQUEST,"Identificador externo duplicado no arquivo.");}
  return normalized;
 }
 @Transactional(readOnly=true) public Map<String,Object> preview(Actor a,CsvInput input){account(a,input.accountId());return Map.of("lines",List.copyOf(normalize(StatementCsv.parse(input)).values()));}
 @Transactional public ImportView importLines(Actor a,Input input){
  var normalized=normalize(input);String reference=input.reference().trim();var fingerprints=normalized.values().stream().map(l->StockService.fingerprint("BANK_LINE",l.externalId(),l.postedOn(),l.amount(),l.description())).toList();String fingerprint=StockService.fingerprint("BANK_IMPORT",input.accountId(),reference,String.join("|",fingerprints));
  lock(a);account(a,input.accountId());var old=db.query("SELECT id,fingerprint FROM bank_import WHERE tenant_id=? AND request_id=?",(r,i)->Map.entry(r.getObject(1,UUID.class),r.getString(2)),a.tenantId(),input.requestId());
  if(!old.isEmpty()){if(!old.getFirst().getValue().equals(fingerprint))throw error(HttpStatus.CONFLICT,"Identificador de importação reutilizado com outros dados.");return imported(a,old.getFirst().getKey());}
  var ids=new ArrayList<UUID>();int created=0;
  for(var l:normalized.values()){
   String hash=StockService.fingerprint("BANK_LINE",l.externalId(),l.postedOn(),l.amount(),l.description());var existing=db.query("SELECT id,fingerprint FROM bank_statement_line WHERE tenant_id=? AND account_id=? AND external_id=?",(r,i)->Map.entry(r.getObject(1,UUID.class),r.getString(2)),a.tenantId(),input.accountId(),l.externalId());
   if(!existing.isEmpty()){if(!hash.equals(existing.getFirst().getValue()))throw error(HttpStatus.CONFLICT,"Identificador externo já importado com conteúdo diferente.");ids.add(existing.getFirst().getKey());continue;}
   UUID id=UUID.randomUUID();db.update("INSERT INTO bank_statement_line(id,tenant_id,account_id,external_id,fingerprint,posted_on,amount,description) VALUES(?,?,?,?,?,?,?,?)",id,a.tenantId(),input.accountId(),l.externalId(),hash,l.postedOn(),l.amount(),l.description());ids.add(id);created++;
  }
  UUID id=UUID.randomUUID();db.update("INSERT INTO bank_import(id,tenant_id,account_id,request_id,fingerprint,reference,new_count,reused_count,created_by,created_at) VALUES(?,?,?,?,?,?,?,?,?,?)",id,a.tenantId(),input.accountId(),input.requestId(),fingerprint,reference,created,ids.size()-created,a.userId(),OffsetDateTime.now(ZoneOffset.UTC));for(var line:ids)db.update("INSERT INTO bank_import_line(tenant_id,import_id,line_id) VALUES(?,?,?)",a.tenantId(),id,line);audit.record(a,"BANK_STATEMENT_IMPORTED",id);return imported(a,id);
 }
 @Transactional(readOnly=true) public Map<String,Object> imports(Actor a,UUID id,int page,int size){account(a,id);var ids=db.query("SELECT id FROM bank_import WHERE tenant_id=? AND account_id=? ORDER BY created_at DESC,id LIMIT ? OFFSET ?",(r,i)->r.getObject(1,UUID.class),a.tenantId(),id,size,(long)page*size);return Map.of("items",ids.stream().map(v->imported(a,v)).toList(),"total",db.queryForObject("SELECT COUNT(*) FROM bank_import WHERE tenant_id=? AND account_id=?",Long.class,a.tenantId(),id),"page",page,"size",size);}
 @Transactional(readOnly=true) public Map<String,Object> lines(Actor a,UUID id,String status,UUID importId,int page,int size){account(a,id);if(importId!=null&&!imported(a,importId).accountId().equals(id))throw error(HttpStatus.NOT_FOUND,"Importação não encontrada.");String where=" WHERE l.tenant_id=? AND l.account_id=? AND (?='' OR l.status=?)"+(importId==null?"":" AND EXISTS(SELECT 1 FROM bank_import_line b WHERE b.tenant_id=l.tenant_id AND b.line_id=l.id AND b.import_id=?)");var args=new ArrayList<Object>(List.of(a.tenantId(),id,status,status));if(importId!=null)args.add(importId);Long total=db.queryForObject("SELECT COUNT(*) FROM bank_statement_line l"+where,Long.class,args.toArray());args.add(size);args.add((long)page*size);return Map.of("items",db.query("SELECT l.* FROM bank_statement_line l"+where+" ORDER BY l.posted_on DESC,l.external_id,l.id LIMIT ? OFFSET ?",this::row,args.toArray()),"total",total,"page",page,"size",size);}
 @Transactional(readOnly=true) public Map<String,Object> summary(Actor a,UUID id){account(a,id);var counts=db.query("SELECT status,COUNT(*) AS total FROM bank_statement_line WHERE tenant_id=? AND account_id=? GROUP BY status",(r,i)->Map.entry(r.getString(1),r.getLong(2)),a.tenantId(),id);var result=new HashMap<String,Object>();for(String state:List.of("UNMATCHED","MATCHED","IGNORED"))result.put(state,0L);for(var count:counts)result.put(count.getKey(),count.getValue());return result;}
 @Transactional(readOnly=true) public Map<String,Object> candidates(Actor a,UUID id,int page,int size){var l=find(a,id);OffsetDateTime from=l.postedOn().minusDays(7).atStartOfDay(zone).toOffsetDateTime(),to=l.postedOn().plusDays(8).atStartOfDay(zone).toOffsetDateTime();String where=" FROM treasury_entry e JOIN treasury_operation o ON o.tenant_id=e.tenant_id AND o.id=e.operation_id WHERE e.tenant_id=? AND e.account_id=? AND e.delta=? AND o.created_at>=? AND o.created_at<? AND NOT EXISTS(SELECT 1 FROM bank_statement_line b WHERE b.tenant_id=e.tenant_id AND b.matched_entry_id=e.id)";var items=db.query("SELECT e.id,e.operation_id,e.delta,o.note,o.origin,o.created_at"+where+" ORDER BY o.created_at DESC,e.id LIMIT ? OFFSET ?",(r,i)->new Candidate(r.getObject("id",UUID.class),r.getObject("operation_id",UUID.class),r.getBigDecimal("delta"),r.getString("note"),r.getString("origin"),r.getObject("created_at",OffsetDateTime.class)),a.tenantId(),l.accountId(),l.amount(),from,to,size,(long)page*size);return Map.of("items",items,"total",db.queryForObject("SELECT COUNT(*)"+where,Long.class,a.tenantId(),l.accountId(),l.amount(),from,to),"page",page,"size",size);}
 @Transactional public Line review(Actor a,UUID id,String action,Review input){
  lock(a);var l=find(a,id);String note=input.note().trim();if(note.length()<5)throw error(HttpStatus.BAD_REQUEST,"Justificativa deve conter cinco caracteres.");if(action.equals("MATCH")!=(input.entryId()!=null))throw error(HttpStatus.BAD_REQUEST,"Informe um lançamento somente na conciliação.");
  String hash=StockService.fingerprint("BANK_REVIEW",id,action,input.version(),input.entryId(),note);var old=db.query("SELECT fingerprint FROM bank_statement_review WHERE tenant_id=? AND request_id=?",(r,i)->r.getString(1),a.tenantId(),input.requestId());if(!old.isEmpty()){if(!old.getFirst().equals(hash))throw error(HttpStatus.CONFLICT,"Identificador de revisão reutilizado com outros dados.");return l;}
  if(l.version()!=input.version())throw error(HttpStatus.CONFLICT,"Extrato alterado por outro acesso. Atualize.");if(action.equals("RESET")?l.status().equals("UNMATCHED"):!l.status().equals("UNMATCHED"))throw error(HttpStatus.CONFLICT,"Situação incompatível. Desfaça a revisão antes de conciliar novamente.");
  if(action.equals("MATCH")){
   var amounts=db.query("SELECT delta FROM treasury_entry WHERE tenant_id=? AND account_id=? AND id=?",(r,i)->r.getBigDecimal(1),a.tenantId(),l.accountId(),input.entryId());if(amounts.isEmpty())throw error(HttpStatus.NOT_FOUND,"Lançamento de tesouraria não encontrado.");if(amounts.getFirst().compareTo(l.amount())!=0)throw error(HttpStatus.CONFLICT,"Valor ou sinal não corresponde ao extrato.");if(db.queryForObject("SELECT COUNT(*) FROM bank_statement_line WHERE tenant_id=? AND matched_entry_id=?",Long.class,a.tenantId(),input.entryId())>0)throw error(HttpStatus.CONFLICT,"Lançamento já conciliado em outra linha.");
  }
  String state=action.equals("MATCH")?"MATCHED":action.equals("IGNORE")?"IGNORED":"UNMATCHED";boolean reset=action.equals("RESET");db.update("UPDATE bank_statement_line SET status=?,version=version+1,matched_entry_id=?,review_note=?,reviewed_by=?,reviewed_at=? WHERE tenant_id=? AND id=?",state,input.entryId(),reset?null:note,reset?null:a.userId(),reset?null:OffsetDateTime.now(ZoneOffset.UTC),a.tenantId(),id);
  db.update("INSERT INTO bank_statement_review(id,tenant_id,line_id,request_id,fingerprint,action,entry_id,note,created_by,line_version,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)",UUID.randomUUID(),a.tenantId(),id,input.requestId(),hash,action,input.entryId(),note,a.userId(),l.version()+1,OffsetDateTime.now(ZoneOffset.UTC));audit.record(a,"BANK_STATEMENT_"+action,id);return find(a,id);
 }
 @Transactional(readOnly=true) public Map<String,Object> history(Actor a,UUID id,int page,int size){find(a,id);var items=db.query("SELECT * FROM bank_statement_review WHERE tenant_id=? AND line_id=? ORDER BY line_version DESC LIMIT ? OFFSET ?",(r,i)->new History(r.getObject("id",UUID.class),r.getString("action"),r.getObject("entry_id",UUID.class),r.getString("note"),r.getObject("created_by",UUID.class),r.getObject("created_at",OffsetDateTime.class),r.getLong("line_version")),a.tenantId(),id,size,(long)page*size);return Map.of("items",items,"total",db.queryForObject("SELECT COUNT(*) FROM bank_statement_review WHERE tenant_id=? AND line_id=?",Long.class,a.tenantId(),id),"page",page,"size",size);}
}
